pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(0) && nonOwner != c.owner());
        vm.assume(newOwner != address(0) && newOwner != c.owner());

        vm.prank(nonOwner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() != newOwner);
    }
}

