pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != c.owner());

        address originalOwner = c.owner();
        vm.prank(nonOwner);
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }

        bool unchanged = (c.owner() == originalOwner);
        assertTrue(unchanged ? !reverted : reverted);
    }
}

