pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // set initial owner to this contract so we can call transferOwnership
        vm.prank(address(this));
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address newOwner) public {
        // The only precondition: caller must be owner. We prank as this contract (the current owner).
        // newOwner can be any address, including zero address or self, to keep domain wide.
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

