pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // Restrict actor to a non-zero address so onlyOwner behaves as intended
        vm.assume(actor != address(0));
        // Set up the initial owner
        vm.prank(actor);
        c.transferOwnership(actor);

        // Record owner before calling owned
        address ownerBefore = c.owner();

        // Drive the entry point that uses the modifier
        vm.prank(actor);
        c.owned();

        // Read owner after the call
        address ownerAfter = c.owner();

        // The general rule: owner must be unchanged by owned().
        // The reference satisfies this for all admissible inputs;
        // the buggy version sets owner to address(0) in the modifier,
        // so ownerBefore != ownerAfter for any call.
        assertTrue(ownerBefore == ownerAfter);
    }
}

