pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // In the correct version, only the current owner (address(this) in setUp) can call transferOwnership.
        // We prank as the current owner (address(this)) to set a new owner.
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // Now the owner should be newOwner. Attempt to call transferOwnership as newOwner should succeed
        // in the correct version but fail in the mutant (which requires non-owner).
        bool ok;
        vm.prank(newOwner);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // Correct: newOwner can transfer ownership (since they are owner), so ok == true.
        // Mutant: newOwner cannot transfer ownership (since they are now owner, and mutant requires non-owner), so ok == false.
        assertTrue(ok);
    }
}
